public static void main(Args _args)
{
    if (_args == null 
        || _args.record() == null
        || _args.record().TableId != tableNum(ISMBatchableTelemetryParameterSetup))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    ISMBatchableTelemetryParameterSetup batchableTelemetryParameterSetup = 
        _args.record() as ISMBatchableTelemetryParameterSetup;

    BatchHeader batchHeader;
    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption("Batch to collect telemetry");

    ISMBatchableTelemetryController batchableTelemetryController 
        = new ISMBatchableTelemetryController();
    Object contract = batchableTelemetryController.getDataContractObject();
    ISMBatchableTelemetryContract batchableTelemetryContract;
    if (contract && contract is ISMBatchableTelemetryContract)
    {
        batchableTelemetryContract = contract as ISMBatchableTelemetryContract;
        batchableTelemetryContract.parmBatchableTelemetryTaskServiceClass(
            batchableTelemetryParameterSetup.BatchableTelemetryTaskServiceClass);
        batchableTelemetryContract.parmBatchableTelemetryTaskServiceMethod(
            'processOperation');
    }
    // update data contract
    batchHeader.addTask(batchableTelemetryController);
    batchHeader.save();

    info(strFmt("Batch job scheduled: %1", batchHeader.parmBatchHeaderId()));

}
